const input = $input.first()?.json ?? {};
const body = input.body ?? input;
const output = {
  event: 'cherry.simulation_result',
  source: 'cherry',
  repo: body.repository?.full_name ?? body.repo ?? 'div0rce/cherry',
  timestamp: body.timestamp ?? body.workflow_run?.updated_at ?? body.pull_request?.updated_at ?? body.issue?.updated_at ?? new Date().toISOString(),
  payload: body,
  workflow: '06_simulation_drift_detector',
  ok: true,
  status: 'accepted',
  summary: 'Normalized cherry.simulation_result.',
  actions: []
};
return [{ json: output }];

const event = $input.first()?.json ?? {};
const fields = ["payload.runId"];
const missing = fields.filter((field) => field.split('.').reduce((value, key) => value?.[key], event) === undefined);
const output = { ...event, valid: missing.length === 0, validationErrors: missing, status: missing.length === 0 ? event.status : 'failed', summary: missing.length === 0 ? event.summary : 'Payload missing required fields: ' + missing.join(', ') };
return [{ json: output }];

const result = $input.first()?.json ?? {};
const event = $node['Normalize Simulation Result'].json;
const comparison = result.comparisonOutput ?? {};
const drift = comparison.drift === true;
const reasons = comparison.reasons ?? [];
const output = {
  ...event,
  automationSnapshotId: result.snapshotId,
  outputHash: result.outputHash,
  drift,
  driftReasons: reasons,
  issueBody: {
    title: '[simulation-drift] ' + (event.payload?.scenarioId ?? event.payload?.profileId ?? 'default'),
    labels: ['simulation-drift', 'automation', 'needs-human-review'],
    body: 'Cherry simulation drift detected.\n\n' + reasons.map((reason) => '- ' + reason).join('\n') + '\n\nSnapshot comparison is stored by Cherry automation, not n8n static data.'
  },
  status: drift ? 'accepted' : 'ignored',
  summary: drift ? 'Simulation drift detected: ' + reasons.join(', ') : 'Simulation snapshot stored with no material drift.',
  actions: drift ? ['compare_snapshot_in_cherry', 'create_issue', 'archive_event'] : ['compare_snapshot_in_cherry', 'archive_event']
};
return [{ json: output }];

const event = $input.first()?.json ?? {};
const output = { ...event, workflow: event.workflow ?? '06_simulation_drift_detector', sinkRouting: {
  discord: '{{ $env.DISCORD_WEBHOOK_URL }}', slack: '{{ $env.SLACK_WEBHOOK_URL }}', email: '{{ $env.EMAIL_WEBHOOK_URL }}', notion: '{{ $env.NOTION_WEBHOOK_URL }}', googleSheets: '{{ $env.GOOGLE_SHEETS_WEBHOOK_URL }}', linearJira: '{{ $env.LINEAR_JIRA_WEBHOOK_URL }}', githubProjects: '{{ $env.GITHUB_PROJECTS_WEBHOOK_URL }}', archive: '{{ $env.CHERRY_API_BASE_URL }}/api/automation/events', incidentTimeline: '{{ $env.CHERRY_API_BASE_URL }}/api/automation/incident-timeline' } };
return [{ json: output }];

const event = $input.first()?.json ?? {};
const output = { ok: event.ok !== false, workflow: event.workflow, status: event.status ?? 'accepted', summary: event.summary ?? 'Simulation drift handled.', actions: event.actions ?? [] };
return [{ json: output }];

const event = $input.first()?.json ?? {};
const output = { ok: event.ok !== false, workflow: event.workflow, status: event.status ?? 'accepted', summary: event.summary ?? 'Simulation snapshot stored.', actions: event.actions ?? [] };
return [{ json: output }];
